    const closeWatcher = () => {
        watcherState.isClosed = true;
        for (const timer of settleTimersByPath.values()) clearTimeout(timer);
        settleTimersByPath.clear();
        if (watcherState.subscription) void closeProjectWatcher(watcherState.subscription);
    };
